<script lang="ts">
 import {useLocale,text} from '$lib/shared/presentation/locale';
 import {copy,noticeText,failureCode} from '$lib/shared/presentation/copy';
 const {locale,change:changeLanguage}=useLocale();
 import {onMount} from 'svelte';
 import type {TitleDetail} from '../../catalog/application/catalog';
 import type {ReadingGateway,Selection} from '../application/progress';
 let {title,readingGateway}:{title:TitleDetail;readingGateway:ReadingGateway}=$props();
 let account=$state<string|null>(null),selection=$state<Selection>({titleId:'',status:'reading',favorite:false,preferredTeamId:'',notify:true}),busy=$state(true),message=$state(''),resume=$state('');
 onMount(()=>{void(async()=>{try{account=await readingGateway.account();if(account){const item=await readingGateway.selection(account,title.id);if(item){selection={...item};resume=item.progress.releaseId;}}selection.titleId=title.id;}catch{message="library_failed";}finally{busy=false;}})();});
 async function save(){if(!account)return;busy=true;try{await readingGateway.save(account,selection);message="library_saved";}catch(failure){message=failureCode(failure);}finally{busy=false;}}
</script>
<section class="selection"><h2>{copy($locale,"Менің кітапханам")}</h2>{#if busy}<p role="status">{copy($locale,"Жүктелуде…")}</p>{:else if account}<form onsubmit={event=>{event.preventDefault();void save();}}><label>{copy($locale,"Оқу мәртебесі")}<select bind:value={selection.status}><option value="reading">{copy($locale,"Оқып жүрмін")}</option><option value="planned">{copy($locale,"Жоспарда")}</option><option value="completed">{copy($locale,"Оқып болдым")}</option><option value="paused">{copy($locale,"Үзілісте")}</option><option value="dropped">{copy($locale,"Тоқтаттым")}</option></select></label><label>{copy($locale,"Қалаған аударма тобы")}<select bind:value={selection.preferredTeamId}><option value="">{copy($locale,"Таңдалмаған")}</option>{#each title.projects as project}<option value={project.teamId}>{project.teamName}</option>{/each}</select></label><label class="check"><input type="checkbox" bind:checked={selection.favorite}/>{copy($locale,"Таңдаулы")}</label><label class="check"><input type="checkbox" bind:checked={selection.notify}/>{copy($locale,"Жаңа тараулар туралы хабарлау")}</label><button class="button primary" disabled={busy}>{copy($locale,"Сақтау")}</button>{#if resume}<a class="button subtle" href={`/read/${resume}`}>{copy($locale,"Оқуды жалғастыру")}</a>{/if}</form>{:else}<p class="muted">{copy($locale,"Оқу орны қонақ ретінде де құрылғыда сақталады. Кітапхана үшін ")}<a class="auth-link" href={'/login?returnTo='+encodeURIComponent('/titles/'+title.slug)}>{copy($locale,"кіріңіз")}</a>.</p>{/if}{#if message}<p role="status">{noticeText($locale,message)}</p>{/if}</section>
<style>.selection{border-block:1px solid var(--line);margin-top:24px;padding:20px 0}.selection h2{font-size:20px;margin-bottom:16px}form{display:flex;flex-wrap:wrap;align-items:end;gap:12px}label{display:grid;gap:8px;font-size:13px;flex:1 1 200px}.check{display:flex;align-items:center;min-height:44px;gap:8px}.check input{width:20px;height:20px;min-height:20px}</style>
